import PropTypes from 'prop-types';
import React from 'react';

import styles from './spinner.css';

/* Local copy of openblock-gui's Spinner — see spinner.css for why. */
const Spinner = ({small}) => (
    <div className={[styles.spinner, small ? styles.small : ''].join(' ').trim()} />
);

Spinner.propTypes = {
    small: PropTypes.bool
};

Spinner.defaultProps = {
    small: false
};

export default Spinner;
