import React, {useState, useCallback, useEffect} from 'react';
import PropTypes from 'prop-types';
import MLProjectsPage    from '../ml-projects-page/ml-projects-page.jsx';
import CreateProjectModal from '../create-project-modal/create-project-modal.jsx';
import MLTrainingPage    from '../ml-training-page/ml-training-page.jsx';
import MLLoader          from '../ml-loader/ml-loader.jsx';
import {deleteProjectData} from '../../lib/ml-engine.js';
import {saveTextProject, saveImageProject, saveAudioProject} from '../../lib/project-persistence.js';
import showAppDialog from '../../lib/app-dialog-service.js';

class TrainingErrorBoundary extends React.Component {
    constructor (props) {
        super(props);
        this.state = {error: null};
        this.handleRetry = this.handleRetry.bind(this);
    }
    static getDerivedStateFromError (error) {
        return {error};
    }
    componentDidCatch (error, info) {
        console.error('[MLStudio] Unhandled render error:', error, info && info.componentStack);
    }
    handleRetry () {
        this.setState({error: null});
        if (this.props.onRetry) this.props.onRetry();
    }
    render () {
        if (this.state.error) {
            return (
                <div style={{
                    display: 'flex', flexDirection: 'column', alignItems: 'center',
                    justifyContent: 'center', height: '100vh',
                    fontFamily: '"Helvetica Neue", Helvetica, Arial, sans-serif',
                    background: '#f8f9fa', color: '#333', padding: 40, textAlign: 'center'
                }}>
                    <div style={{fontSize: 48, marginBottom: 16}}>⚠️</div>
                    <h2 style={{margin: '0 0 8px', fontSize: 22, fontWeight: 700}}>Something went wrong</h2>
                    <p style={{margin: '0 0 24px', color: '#888', fontSize: 14, maxWidth: 420}}>
                        {this.state.error.message || 'An unexpected error occurred in the ML environment.'}
                    </p>
                    <button
                        onClick={this.handleRetry}
                        style={{
                            background: '#004AAD', color: 'white', border: 'none',
                            borderRadius: 10, padding: '11px 28px', fontSize: 14,
                            fontWeight: 700, cursor: 'pointer'
                        }}
                    >
                        Go Back to Projects
                    </button>
                </div>
            );
        }
        return this.props.children;
    }
}
TrainingErrorBoundary.propTypes = {
    children: PropTypes.node,
    onRetry:  PropTypes.func
};

const getIpc = () => {
    try { return window.require('electron').ipcRenderer; } catch (_) { return null; }
};

const generateId = () => Math.random().toString(36).slice(2, 10);

/* ─── MLStudioApp ─────────────────────────────────
   Project list is persisted on disk:
     <userData>/ml-projects/<projectId>/project.json

   On mount we ask the main process to scan that
   directory and return all project metadata.
   Writes happen whenever a training page saves.
──────────────────────────────────────────────────── */
const MLStudioApp = ({onEnterBlocks, onBack}) => {
    const [view,            setView]      = useState('mlProjects');
    const [projects,        setProjects]  = useState([]);
    const [loading,         setLoading]   = useState(true);
    const [loadingMsg,      setLoadingMsg] = useState('Loading projects…');
    const [activeProject,   setActive]    = useState(null);
    const [showCreateModal, setShowCreate] = useState(false);

    /* ── Load project list from disk on mount ── */
    useEffect(() => {
        const ipc = getIpc();
        if (!ipc) { setLoading(false); return; }
        const scan = () => ipc.invoke('ml-list-projects')
            .then(list => (Array.isArray(list) ? list : []))
            .catch(() => []);
        (async () => {
            let list = await scan();
            // Safety net: if an ML model is active in the blocks editor (e.g. a project
            // opened from a .rc) but its folder isn't on disk yet — because the blocks-side
            // extraction was skipped or mistimed — extract it now so the project always
            // appears here. ml-get-loaded-data extracts the bundled ml/ from the open .rc;
            // if it's already on disk it's a no-op.
            try {
                const active = (typeof window !== 'undefined' && window.__openblockMLModel) || null;
                if (active && active.projectId && !list.some(p => p.id === active.projectId)) {
                    await ipc.invoke('ml-get-loaded-data', active.projectId).catch(() => {});
                    list = await scan();
                }
            } catch (_) { /* ignore — list still shows whatever scanned */ }
            setProjects(list);
            setLoading(false);
        })();
    }, []);

    /* ── Refresh project list from disk (called after save/delete) ── */
    const refreshProjects = useCallback(() => {
        const ipc = getIpc();
        if (!ipc) return;
        ipc.invoke('ml-list-projects').then(list => {
            setProjects(Array.isArray(list) ? list : []);
        }).catch(err => {
            console.error('[MLStudio] ml-list-projects refresh failed:', err);
        });
    }, []);

    /* ── Project CRUD ── */
    const createProject = useCallback(({name, type, description}) => {
        /* Guard against duplicate names */
        const alreadyExists = projects.some(
            p => p.name.toLowerCase() === name.toLowerCase()
        );
        if (alreadyExists) return;

        const p = {
            id:           generateId(),
            name,
            description:  description || '',
            type,
            labels:       ['Class 1', 'Class 2'],
            trainingData: {},
            trained:      false,
            createdAt:    Date.now(),
            updatedAt:    Date.now()
        };
        /* Write the initial project.json to disk immediately so it shows up in the list */
        const ipc = getIpc();
        if (ipc) {
            const saveData = JSON.stringify({
                id:          p.id,
                name:        p.name,
                description: p.description,
                type:        p.type,
                labels:      p.labels,
                trained:     false,
                createdAt:   p.createdAt,
                updatedAt:   p.updatedAt,
                savedAt:     p.createdAt
            });
            ipc.invoke('ml-write-file', p.id, 'project.json', saveData).catch(() => {});
        }
        setShowCreate(false);
        setActive(p);
        setView('mlTraining');
        /* Refresh list after a short delay so the new project.json is on disk */
        setTimeout(refreshProjects, 500);
    }, [refreshProjects, projects]);

    const deleteProject = useCallback(async projectOrId => {
        const id   = typeof projectOrId === 'string' ? projectOrId : projectOrId.id;
        const name = (typeof projectOrId === 'object' && projectOrId && projectOrId.name) || 'this project';
        /* Confirm before destroying the project — deletion is permanent and removes the
           trained model + all training data. */
        const idx = await showAppDialog({
            type:    'warning',
            title:   'Delete ML Project',
            message: `Delete "${name}"?`,
            detail:  'This permanently removes the project, its trained model, and all of its ' +
                'training data. This cannot be undone.',
            buttons: ['Delete', 'Cancel'],
            defaultId: 1
        });
        if (idx !== 0) return; // Cancel — do nothing

        deleteProjectData(id).catch(() => {});
        const ipc = getIpc();
        if (ipc) ipc.invoke('ml-delete-project', id).catch(() => {});
        // Clear pending project in main process so will-download doesn't try to bundle deleted dir
        if (ipc) ipc.send('ml-clear-pending-project', id);
        /* If the deleted project was the active model, clear the global ref and
           notify app.jsx so it doesn't restore the deleted model on Back. */
        if (typeof window !== 'undefined' &&
            window.__openblockMLModel &&
            window.__openblockMLModel.projectId === id) {
            window.__openblockMLModel = null;
            window.dispatchEvent(new CustomEvent('robocoders:ml-model-deleted', {detail: {projectId: id}}));
        }
        /* Optimistically remove from list, then refresh from disk */
        setProjects(prev => prev.filter(p => p.id !== id));
        setTimeout(refreshProjects, 300);
    }, [refreshProjects]);

    /* Read-modify-write a project's project.json on disk, merging only the given
       fields. Critical: rewriting the whole object from the lightweight list-view
       `project` (which has no trainingIndex/disabledLabels) would WIPE the sample
       index and make recorded samples disappear on reload. So we always merge into
       whatever is currently on disk. */
    const patchProjectMeta = useCallback(async (projectId, patch) => {
        const ipc = getIpc();
        if (!ipc) return;
        let current = {};
        try {
            const raw = await ipc.invoke('ml-read-file', projectId, 'project.json');
            if (raw) {
                const text = typeof raw === 'string' ? raw : Buffer.from(raw).toString('utf8');
                current = JSON.parse(text) || {};
            }
        } catch (_) { /* fall back to writing just the patch */ }
        const merged = {...current, ...patch, id: projectId, updatedAt: Date.now()};
        await ipc.invoke('ml-write-file', projectId, 'project.json', JSON.stringify(merged))
            .catch(() => {});
    }, []);

    const renameProject = useCallback((project, newName) => {
        const trimmed = newName.trim();
        if (!trimmed || trimmed === project.name) return;
        /* Prevent duplicate names (case-insensitive) */
        const isDuplicate = projects.some(
            p => p.id !== project.id && p.name.toLowerCase() === trimmed.toLowerCase()
        );
        if (isDuplicate) return;
        setProjects(prev => prev.map(p =>
            p.id === project.id ? {...p, name: trimmed, updatedAt: Date.now()} : p
        ));
        patchProjectMeta(project.id, {name: trimmed});
    }, [projects, patchProjectMeta]);

    const updateProjectDescription = useCallback((project, newDesc) => {
        const trimmed = newDesc.trim();
        setProjects(prev => prev.map(p =>
            p.id === project.id ? {...p, description: trimmed, updatedAt: Date.now()} : p
        ));
        patchProjectMeta(project.id, {description: trimmed});
    }, [patchProjectMeta]);

    const updateProject = useCallback(updated => {
        setActive(updated);
        /* The training pages write project.json to disk themselves via saveXxxProject.
           We just refresh the in-memory list so the dashboard stays current. */
        setProjects(prev => {
            const exists = prev.some(p => p.id === updated.id);
            if (exists) {
                return prev.map(p => p.id === updated.id
                    ? {...p, name: updated.name, labels: updated.labels, trained: updated.trained, updatedAt: Date.now()}
                    : p
                );
            }
            return [...prev, updated];
        });
    }, []);

    /* When returning to the project list, refresh from disk to pick up any saves */
    const handleBackToList = useCallback(() => {
        setView('mlProjects');
        refreshProjects();
    }, [refreshProjects]);

    /* ── Import a .rcml model file ── */
    const importProject = useCallback(() => {
        const ipc = getIpc();
        if (!ipc) return;
        /* Use Electron's file dialog to pick a .rcml file */
        ipc.invoke('ml-open-ob-file').then(result => {
            if (!result || result.canceled) return;
            if (result.error) {
                // eslint-disable-next-line no-alert
                alert(`Could not import model: ${result.error}`);
                return;
            }
            if (!result.projectId) {
                // eslint-disable-next-line no-alert
                alert('Could not import model: no ML model found in the selected file.');
                return;
            }
            /* The main process extracted the model to ml-projects/<projectId>/.
               Re-scan the list, then open the imported project so the user gets
               clear feedback (especially when re-importing an id that already exists). */
            ipc.invoke('ml-list-projects').then(list => {
                const arr = Array.isArray(list) ? list : [];
                setProjects(arr);
                const imported = arr.find(p => p.id === result.projectId);
                if (imported) {
                    handleOpenProject(imported);
                } else {
                    // eslint-disable-next-line no-alert
                    alert(`Imported "${result.name || 'model'}". It is now in your project list.`);
                }
            }).catch(() => refreshProjects());
        }).catch(() => {
            /* Fallback: just open a file input for JSON import */
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = '.json,.mlproject';
            input.onchange = e => {
                const file = e.target.files[0];
                if (!file) return;
                const reader = new FileReader();
                reader.onload = evt => {
                    try {
                        const p = JSON.parse(evt.target.result);
                        if (!p.name || !p.type) throw new Error('Invalid project file');
                        const imported = {
                            ...p,
                            id:           generateId(),
                            createdAt:    Date.now(),
                            updatedAt:    Date.now(),
                            trained:      false,
                            trainingData: {}
                        };
                        setActive(imported);
                        setView('mlTraining');
                    } catch (err) {
                        console.error('[MLStudio] Import failed:', err);
                    }
                };
                reader.readAsText(file);
            };
            input.click();
        });
    }, [refreshProjects]);

    /* ── Download a project's model as a standalone .rcml ── */
    const exportProject = useCallback(project => {
        const ipc = getIpc();
        if (!ipc || !project) return;
        if (!project.trained) {
            // eslint-disable-next-line no-alert
            alert('This model has not been trained yet. Train it before downloading.');
            return;
        }
        ipc.invoke('ml-save-ob-file', project.id, project.name).catch(err => {
            console.error('[MLStudio] Download model failed:', err);
        });
    }, []);

    /* Show branded loader during initial project list fetch */
    if (loading) return <MLLoader message={loadingMsg} />;

    /* Open a project with a brief transition loader */
    const handleOpenProject = p => {
        setLoadingMsg('Opening project…');
        setLoading(true);
        setActive(p);
        /* Let the loader render for one frame, then switch view */
        setTimeout(() => {
            setView('mlTraining');
            setLoading(false);
        }, 0);
    };

    /* ── View routing ── */
    if (view === 'mlTraining' && activeProject) {
        return (
            <TrainingErrorBoundary onRetry={handleBackToList}>
                <MLTrainingPage
                    project={activeProject}
                    onBack={handleBackToList}
                    onUseInBlocks={onEnterBlocks}
                    onUpdateProject={updateProject}
                />
            </TrainingErrorBoundary>
        );
    }

    return (
        <>
            <MLProjectsPage
                projects={projects}
                loading={false}
                onBack={onBack}
                onCreate={() => setShowCreate(true)}
                onOpen={handleOpenProject}
                onDelete={deleteProject}
                onRename={renameProject}
                onUpdateDescription={updateProjectDescription}
                onImport={importProject}
                onExport={exportProject}
            />
            {showCreateModal && (
                <CreateProjectModal
                    onCancel={() => setShowCreate(false)}
                    onCreate={createProject}
                    existingNames={projects.map(p => p.name)}
                />
            )}
        </>
    );
};

MLStudioApp.propTypes = {
    onEnterBlocks: PropTypes.func.isRequired,
    onBack:        PropTypes.func.isRequired
};

export default MLStudioApp;
