/* ── Browser-native .rcml import/export ──────────────────────────────
   Desktop produces/reads .rcml as a ZIP (via `jszip` + Node fs, see
   openblock-desktop/src/main/index.js's bundleMLDir/extractMLDir) with this
   layout, matched exactly here so files are portable between desktop and web:

     ml/project.json           – {id, name, type, labels, disabledLabels,
                                   trainingIndex, trained, createdAt, updatedAt, savedAt}
     ml/images/<id>             – image data-URL (images projects)
     ml/audio/<id>.json         – {data:[...], frameSize} (sounds projects)
     ml/thumbs/<id>              – waveform thumbnail data-URL (sounds)
     ml/blobs/<id>.meta / .bin   – raw audio blob mime + bytes (sounds)
     ml/image-model/model.json + weights.bin   – trained MobileNet head (images)
     ml/audio-model/model.json + weights.bin   – trained transfer model (sounds)
     ml/text-model/classifier.json             – serialized KNN + vocab (text)

   trainingIndex is {label: [sampleId, ...]} for images/sounds, or
   {label: [{id, text}, ...]} for text (text samples are stored inline, no
   separate per-sample file — matches project-persistence.js's desktop format).
   ─────────────────────────────────────────────────────────────────── */
import JSZip from 'jszip';

import {
    getImageFromIDB, saveImageToIDB,
    getAudioFromIDB, saveAudioToIDB,
    getAudioThumbFromIDB, saveAudioThumbToIDB,
    getAudioBlobFromIDB, saveAudioBlobToIDB,
    idbGetFile, idbPutFile
} from './idb.js';

const getTF = async () => {
    const m = await import(/* webpackChunkName: "tfjs" */ '@tensorflow/tfjs');
    return m.default || m;
};

/* ── Model save/load via the same indexeddb:// scheme ml-engine.js uses ── */
const exportModelFiles = async (zip, subDir, projectId) => {
    try {
        const tf = await getTF();
        const model = await tf.loadLayersModel(`indexeddb://ml-${subDir}-${projectId}`);
        let artifacts = null;
        await model.save(tf.io.withSaveHandler(async a => {
            artifacts = a;
            return {modelArtifactsInfo: {dateSaved: new Date(), modelTopologyType: 'JSON'}};
        }));
        if (!artifacts) return false;
        zip.file(`ml/${subDir}/model.json`, JSON.stringify({
            modelTopology: artifacts.modelTopology,
            weightsManifest: [{paths: ['weights.bin'], weights: artifacts.weightSpecs}]
        }));
        zip.file(`ml/${subDir}/weights.bin`, artifacts.weightData);
        return true;
    } catch (_) {
        return false; // no trained model bundled for this project — fine
    }
};

const importModelFiles = async (zip, subDir, projectId) => {
    const modelEntry = zip.file(`ml/${subDir}/model.json`);
    const weightsEntry = zip.file(`ml/${subDir}/weights.bin`);
    if (!modelEntry || !weightsEntry) return false;
    const tf = await getTF();
    const parsed = JSON.parse(await modelEntry.async('string'));
    const weightData = await weightsEntry.async('arraybuffer');
    const model = await tf.loadLayersModel(tf.io.fromMemory({
        modelTopology: parsed.modelTopology,
        weightSpecs: parsed.weightsManifest[0].weights,
        weightData
    }));
    await model.save(`indexeddb://ml-${subDir}-${projectId}`);
    return true;
};

/**
 * Bundle a project (gui.jsx's in-memory shape: {id, name, type, labels,
 * disabledLabels, trainingData, trained, createdAt}) into a .rcml file and
 * trigger a browser download.
 */
export const exportProjectToRcml = async project => {
    const zip = new JSZip();
    const trainingIndex = {};
    if (project.type === 'text') {
        for (const [label, samples] of Object.entries(project.trainingData || {})) {
            trainingIndex[label] = (samples || []).map(s => ({id: s.id, text: s.text || ''}));
        }
    } else {
        for (const [label, samples] of Object.entries(project.trainingData || {})) {
            trainingIndex[label] = (samples || []).map(s => s.id);
        }
    }

    const now = Date.now();
    zip.file('ml/project.json', JSON.stringify({
        id: project.id,
        name: project.name,
        type: project.type,
        labels: project.labels || [],
        disabledLabels: project.disabledLabels || [],
        trainingIndex,
        trained: !!project.trained,
        createdAt: project.createdAt || now,
        updatedAt: now,
        savedAt: now
    }));

    if (project.type === 'images') {
        for (const samples of Object.values(project.trainingData || {})) {
            for (const s of (samples || [])) {
                const data = s.data || await getImageFromIDB(project.id, s.id);
                if (data) zip.file(`ml/images/${s.id}`, data);
            }
        }
        if (project.trained) await exportModelFiles(zip, 'image-model', project.id);
    } else if (project.type === 'sounds') {
        for (const samples of Object.values(project.trainingData || {})) {
            for (const s of (samples || [])) {
                const stored = await getAudioFromIDB(project.id, s.id);
                const spectrogramData = s.spectrogramData || (stored && stored.data);
                const frameSize = s.frameSize || (stored && stored.frameSize);
                if (spectrogramData) {
                    zip.file(`ml/audio/${s.id}.json`, JSON.stringify({data: spectrogramData, frameSize}));
                }
                const thumb = await getAudioThumbFromIDB(project.id, s.id);
                if (thumb) zip.file(`ml/thumbs/${s.id}`, thumb);
                const blob = await getAudioBlobFromIDB(project.id, s.id);
                if (blob) {
                    zip.file(`ml/blobs/${s.id}.meta`, blob.type || 'audio/webm');
                    zip.file(`ml/blobs/${s.id}.bin`, await blob.arrayBuffer());
                }
            }
        }
        if (project.trained) await exportModelFiles(zip, 'audio-model', project.id);
    } else if (project.type === 'text') {
        const classifierRaw = await idbGetFile(project.id, 'text-model/classifier.json');
        if (classifierRaw) zip.file('ml/text-model/classifier.json', classifierRaw);
    }

    const blob = await zip.generateAsync({type: 'blob', compression: 'DEFLATE'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${project.name || 'ml-model'}.rcml`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
};

/**
 * Parse an uploaded .rcml (or legacy .rc) File, write its assets into
 * IndexedDB under a fresh project id, and return a gui.jsx-shaped project
 * object ready to add to the project list.
 */
export const importRcmlFile = async file => {
    const buf = await file.arrayBuffer();
    const zip = await JSZip.loadAsync(buf);
    const metaEntry = zip.file('ml/project.json') ||
        Object.keys(zip.files)
            .filter(k => k.startsWith('ml/') && k.endsWith('/project.json'))
            .map(k => zip.files[k])[0];
    if (!metaEntry) throw new Error('No ML model found in this file.');
    const meta = JSON.parse(await metaEntry.async('string'));
    if (!meta || !meta.id) throw new Error('Invalid ML model file.');

    const newId = Math.random().toString(36).slice(2, 10);
    const labels = meta.labels || [];
    const type = meta.type || 'images';
    const trainingData = {};
    for (const label of labels) trainingData[label] = [];

    if (type === 'text') {
        for (const [rawLabel, items] of Object.entries(meta.trainingIndex || {})) {
            if (!trainingData[rawLabel]) trainingData[rawLabel] = [];
            for (const item of (Array.isArray(items) ? items : [])) {
                trainingData[rawLabel].push({id: item.id, type: 'text', text: item.text || ''});
            }
        }
        const classifierEntry = zip.file('ml/text-model/classifier.json');
        if (classifierEntry) {
            await idbPutFile(newId, 'text-model/classifier.json', await classifierEntry.async('string'));
        }
    } else if (type === 'images') {
        for (const [label, ids] of Object.entries(meta.trainingIndex || {})) {
            if (!trainingData[label]) trainingData[label] = [];
            for (const id of (ids || [])) {
                const entry = zip.file(`ml/images/${id}`);
                const data = entry ? await entry.async('string') : '';
                if (data) await saveImageToIDB(newId, id, data);
                trainingData[label].push({id, type: 'image', data});
            }
        }
        if (meta.trained) await importModelFiles(zip, 'image-model', newId);
    } else {
        for (const [label, ids] of Object.entries(meta.trainingIndex || {})) {
            if (!trainingData[label]) trainingData[label] = [];
            for (const id of (ids || [])) {
                let spectrogramData = null, frameSize = null;
                const audioEntry = zip.file(`ml/audio/${id}.json`);
                if (audioEntry) {
                    const parsed = JSON.parse(await audioEntry.async('string'));
                    spectrogramData = parsed.data;
                    frameSize = parsed.frameSize;
                    await saveAudioToIDB(newId, id, spectrogramData, frameSize);
                }
                const thumbEntry = zip.file(`ml/thumbs/${id}`);
                if (thumbEntry) await saveAudioThumbToIDB(newId, id, await thumbEntry.async('string'));
                const metaFileEntry = zip.file(`ml/blobs/${id}.meta`);
                const binEntry = zip.file(`ml/blobs/${id}.bin`);
                if (metaFileEntry && binEntry) {
                    const mime = await metaFileEntry.async('string');
                    const ab = await binEntry.async('arraybuffer');
                    await saveAudioBlobToIDB(newId, id, new Blob([ab], {type: mime}));
                }
                trainingData[label].push({id, type: 'audio', spectrogramData, frameSize});
            }
        }
        if (meta.trained) await importModelFiles(zip, 'audio-model', newId);
    }

    const now = Date.now();
    return {
        id: newId,
        name: meta.name || 'Imported Model',
        type,
        labels,
        disabledLabels: meta.disabledLabels || [],
        trainingData,
        trained: !!meta.trained,
        createdAt: now,
        updatedAt: now
    };
};
